{
  "recipes": [
    {
      "title": "LE SOUFFLÉ AU FROMAGE",
      "type": "plat",
      "servings": 4,
      "ingredients": [
        {
          "raw": "Beurrez un moule à soufflé de 16 cm de diamètre.",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "Préchauffez le four à 180 °C.",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "Cassez 4 œufs en séparant les blancs des jaunes.",
          "quantity": 4,
          "unit": null,
          "label": "œufs"
        },
        {
          "raw": "Mettez les blancs dans un saladier, ajoutez 2 pincées de sel.",
          "quantity": 2,
          "unit": "pincées",
          "label": "sel"
        },
        {
          "raw": "Faites bouillir 25 cl de lait.",
          "quantity": 25,
          "unit": "cl",
          "label": "lait"
        },
        {
          "raw": "Faites fondre 40 g de beurre dans une casserole, ajoutez 40 g de farine et mélangez 1 mn sur feu doux.",
          "quantity": 40,
          "unit": "g",
          "label": "beurre"
        },
        {
          "raw": "Versez le lait bouillant en filet, sans cesser de remuer, et laissez épaissir sur feu doux, en tournant sans cesse 5 mn, jusqu'à obtention d'une crème épaisse.",
          "quantity": 5,
          "unit": "mn",
          "label": null
        },
        {
          "raw": "Retirez du feu et incorporez un à un 3 jaunes d'œufs, en fouettant toujours.",
          "quantity": 3,
          "unit": null,
          "label": "jaunes d'œufs"
        },
        {
          "raw": "Ajoutez 1 c. à soupe de crème épaisse, sel, poivre et noix muscade.",
          "quantity": 1,
          "unit": "c. à soupe",
          "label": "crème épaisse"
        },
        {
          "raw": "Battez les blancs d'œufs en neige pas trop ferme puis ajoutez-en 1/4 dans la casserole.",
          "quantity": null,
          "unit": null,
          "label": "blancs d'œufs"
        },
        {
          "raw": "Mélangez avec une spatule souple en soulevant la préparation (et non en la tournant), en incorporant 100 g de comté râpé par cuillérées.",
          "quantity": 100,
          "unit": "g",
          "label": "comté râpé"
        },
        {
          "raw": "Versez la préparation dans le moule qu'elle doit remplir aux 3/4.",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "Glissez au four et laissez cuire 30 mn, jusqu'à ce que le soufflé soit gonflé et doré.",
          "quantity": 30,
          "unit": "mn",
          "label": null
        },
        {
          "raw": "Servez aussitôt.",
          "quantity": null,
          "unit": null,
          "label": null
        }
      ],
      "steps": [
        "Beurrez un moule à soufflé de 16 cm de diamètre.",
        "Préchauffez le four à 180 °C.",
        "Cassez 4 œufs en séparant les blancs des jaunes.",
        "Mettez les blancs dans un saladier, ajoutez 2 pincées de sel.",
        "Faites bouillir 25 cl de lait.",
        "Faites fondre 40 g de beurre dans une casserole, ajoutez 40 g de farine et mélangez 1 mn sur feu doux.",
        "Versez le lait bouillant en filet, sans cesser de remuer, et laissez épaissir sur feu doux, en tournant sans cesse 5 mn, jusqu'à obtention d'une crème épaisse.",
        "Retirez du feu et incorporez un à un 3 jaunes d'œufs, en fouettant toujours.",
        "Ajoutez 1 c. à soupe de crème épaisse, sel, poivre et noix muscade.",
        "Battez les blancs d'œufs en neige pas trop ferme puis ajoutez-en 1/4 dans la casserole.",
        "Mélangez avec une spatule souple en soulevant la préparation (et non en la tournant), en incorporant 100 g de comté râpé par cuillérées.",
        "Versez la préparation dans le moule qu'elle doit remplir aux 3/4.",
        "Glissez au four et laissez cuire 30 mn, jusqu'à ce que le soufflé soit gonflé et doré.",
        "Servez aussitôt."
      ]
    },
    {
      "title": "LA VERSION LIGHT DE DAVID ZUDDAS",
      "type": "plat",
      "servings": 8,
      "ingredients": [
        {
          "raw": "Bousculé par ce chef ultra créatif, servi avec magret et salade, le soufflé au fromage devient un vrai plat complet et diététiquement correct.",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "Pour 8 personnes.",
          "quantity": 8,
          "unit": null,
          "label": "personnes"
        },
        {
          "raw": "Faites cuire 300 g de pommes de terre à la vapeur puis réduisez-les en fine purée au moulin à légumes.",
          "quantity": 300,
          "unit": "g",
          "label": "pommes de terre"
        },
        {
          "raw": "Incorporez-y 25 cl de lait chaud et 120 g de comté râpé fin.",
          "quantity": 25,
          "unit": "cl",
          "label": "lait chaud"
        },
        {
          "raw": "Ajoutez 6 jaunes d'œufs, puis, délicatement, 8 blancs en neige.",
          "quantity": 6,
          "unit": null,
          "label": "jaunes d'œufs"
        },
        {
          "raw": "Préchauffez le four à 170 °C.",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "Chemisez 8 cercles de papier sulfurisé, en le faisant dépasser.",
          "quantity": 8,
          "unit": null,
          "label": "cercles de papier sulfurisé"
        },
        {
          "raw": "Versez-y la préparation et glissez 15 mn au four.",
          "quantity": 15,
          "unit": "mn",
          "label": null
        },
        {
          "raw": "Lorsque les soufflés sont cuits, dressez-les dans des assiettes et retirez le cercle et le papier.",
          "quantity": null,
          "unit": null,
          "label": null
        },
        {
          "raw": "Servez aussitôt, accompagné de mesclun et de tranches de magret fumé.",
          "quantity": null,
          "unit": null,
          "label": null
        }
      ],
      "steps": [
        "Bousculé par ce chef ultra créatif, servi avec magret et salade, le soufflé au fromage devient un vrai plat complet et diététiquement correct.",
        "Faites cuire 300 g de pommes de terre à la vapeur puis réduisez-les en fine purée au moulin à légumes.",
        "Incorporez-y 25 cl de lait chaud et 120 g de comté râpé fin.",
        "Ajoutez 6 jaunes d'œufs, puis, délicatement, 8 blancs en neige.",
        "Préchauffez le four à 170 °C.",
        "Chemisez 8 cercles de papier sulfurisé, en le faisant dépasser.",
        "Versez-y la préparation et glissez 15 mn au four.",
        "Lorsque les soufflés sont cuits, dressez-les dans des assiettes et retirez le cercle et le papier.",
        "Servez aussitôt, accompagné de mesclun et de tranches de magret fumé."
      ]
    }
  ]
}
